// Site override of themes/tabi/static/js/giscus.min.js (same path, so Zola
// serves this one; tabi's comments.html loads it with `async`). Not minified
// on purpose. Changes from tabi's giscus.js:
//
// 1. Themes ending in .css (static/giscus/*.css) are resolved to full URLs
//    relative to the site root, which giscus requires. Resolving from this
//    script's own URL keeps it working on the GitHub Pages preview, which is
//    served from a subfolder.
// 2. The site theme is re-sent once the giscus iframe reports in. Comments
//    load lazily, so a theme toggle before scrolling down used to be lost and
//    the comments came up in the old theme.

(function () {
    const thisScript = document.currentScript;
    const siteRoot = thisScript
        ? new URL('../', thisScript.src)
        : new URL('/', window.location.href);

    function resolveTheme(theme) {
        return theme && theme.endsWith('.css')
            ? new URL(theme.replace(/^\//, ''), siteRoot).href
            : theme;
    }

    const commentsDiv = document.querySelector('.comments');
    if (!commentsDiv) return;

    const lightTheme = resolveTheme(commentsDiv.getAttribute('data-light-theme'));
    const darkTheme = resolveTheme(commentsDiv.getAttribute('data-dark-theme'));

    function siteTheme() {
        return document.documentElement.getAttribute('data-theme') === 'dark'
            ? darkTheme
            : lightTheme;
    }

    function setGiscusTheme(theme) {
        const frame = document.querySelector('iframe.giscus-frame');
        if (frame && frame.contentWindow) {
            frame.contentWindow.postMessage(
                { giscus: { setConfig: { theme: theme } } },
                'https://giscus.app'
            );
        }
    }

    const script = document.createElement('script');
    script.src = 'https://giscus.app/client.js';
    script.async = true;

    const passThrough = {
        'data-repo': 'data-repo',
        'data-repo-id': 'data-repo-id',
        'data-category': 'data-category',
        'data-category-id': 'data-category-id',
        'data-term': 'data-term',
        'data-strict': 'data-strict',
        'data-reactions-enabled': 'data-reactions-enabled',
        'data-input-position': 'data-input-position',
        'data-lang': 'data-lang',
    };
    for (const [from, to] of Object.entries(passThrough)) {
        script.setAttribute(to, commentsDiv.getAttribute(from));
    }
    const mapping = commentsDiv.getAttribute('data-mapping');
    if (mapping) script.setAttribute('data-mapping', mapping);
    script.setAttribute('data-emit-metadata', '0');
    script.setAttribute('crossorigin', 'anonymous');
    script.setAttribute('data-theme', siteTheme());
    if (commentsDiv.getAttribute('data-lazy-loading') === 'true') {
        script.setAttribute('data-loading', 'lazy');
    }

    commentsDiv.appendChild(script);

    // Theme switcher / OS change (tabi's themeSwitcher.js fires this).
    window.addEventListener('themeChanged', function (event) {
        setGiscusTheme(event.detail.theme === 'dark' ? darkTheme : lightTheme);
    });

    // First message from the iframe means it is loaded and listening; bring
    // it in line with whatever the site theme is by now.
    let synced = false;
    window.addEventListener('message', function (event) {
        if (synced || event.origin !== 'https://giscus.app') return;
        synced = true;
        setGiscusTheme(siteTheme());
    });
})();
